// Réglages de la sauvegarde.
// DESTINATAIRE : adresse qui reçoit la sauvegarde chaque lundi (boîte perso : le serveur sert tous les projets de Karim).
// INSTANCE     : adresse de l'instance n8n sauvegardée.
return [{ json: { DESTINATAIRE: 'karimbordeau33@gmail.com', INSTANCE: 'https://n8n-jtbx.srv1974245.hstgr.cloud' } }];

// Une ligne par workflow à sauvegarder (tests « ZZ … » et workflows archivés exclus).
// On garde tout ce qu'il faut pour réimporter : nœuds, liaisons, réglages, données statiques.
const reponse = $input.first().json || {};
const workflows = (Array.isArray(reponse.data) ? reponse.data : [])
  .filter(w => w && w.id && !w.isArchived && !String(w.name || '').startsWith('ZZ '));
if (!workflows.length) throw new Error('Sauvegarde vide : aucun workflow lu par l’API n8n');
return workflows.map(w => ({ json: {
  id: w.id, name: w.name, active: w.active, updatedAt: w.updatedAt,
  nodes: w.nodes, connections: w.connections, settings: w.settings,
  staticData: w.staticData || null, pinData: w.pinData || {}, tags: w.tags || []
} }));

// Objet et texte de l'e-mail ; la pièce jointe (fichier JSON) est transmise telle quelle.
const NL = String.fromCharCode(10);
const TZ = 'Europe/Paris';
const quand = new Date().toLocaleDateString('fr-FR', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const wfs = $('Préparation de la sauvegarde').all().map(i => i.json);
const lignes = wfs
  .sort((a, b) => String(a.name).localeCompare(String(b.name)))
  .map(w => '- ' + w.name + (w.active ? ' (publié)' : ' (inactif)') + ' — modifié le ' + new Date(w.updatedAt).toLocaleDateString('fr-FR', { timeZone: TZ }));
const message = [
  'Sauvegarde hebdomadaire de l’instance n8n ' + $('Réglages').first().json.INSTANCE + ' — ' + quand + '.',
  '',
  wfs.length + ' workflows dans la pièce jointe (fichier JSON) :',
  ...lignes,
  '',
  'Restaurer un workflow : ouvrir le fichier, copier l’objet du workflow voulu dans un fichier .json, puis dans n8n « Import from File ».',
  'Les identifiants ne sont pas dans ce fichier : ils se restaurent avec la sauvegarde Hostinger du serveur et la clé de chiffrement rangée dans le gestionnaire de mots de passe.',
  '',
  'Message automatique — workflow « Sauvegarde hebdomadaire des workflows ».'
].join(NL);
return [{ json: { objet: 'Sauvegarde n8n — ' + quand + ' — ' + wfs.length + ' workflows', message }, binary: $input.first().binary }];

